    const attribution = await database.referralAttribution.create({ data: { affiliateId: profile.id, configId: config.id, tokenHash: 'a'.repeat(64), customerTenantId, expiresAt: new Date(Date.now() + 86_400_000) } }); await expect(database.referralAttribution.create({ data: { affiliateId: profile.id, configId: config.id, tokenHash: 'b'.repeat(64), customerTenantId, expiresAt: new Date(Date.now() + 86_400_000) } })).rejects.toThrow();
    const customerRole = await database.role.findFirstOrThrow({ where: { name: 'Customer', tenantId: null } }); await database.userRole.create({ data: { tenantId: affiliateTenantId, userId: affiliateUser.id, roleId: customerRole.id } }); const captured = await app.inject({ method: 'POST', url: '/v1/affiliate/attributions', payload: { code: profile.code } }); const referral = cookieFrom(captured.headers['set-cookie']); expect((await app.inject({ method: 'POST', url: '/v1/affiliate/attributions/claim', headers: { cookie: `${affiliateCookie}; ${referral}` } })).json().error.code).toBe('SELF_REFERRAL_FORBIDDEN');
    const provider = await database.paymentProviderConfig.create({ data: { name: 'Affiliate test', adapterKey: 'none' } }); const payments = [] as string[]; for (let period = 0; period < 3; period += 1) { const payment = await database.paymentTransaction.create({ data: { tenantId: customerTenantId, providerConfigId: provider.id, packageVersionId: version.id, idempotencyKey: crypto.randomUUID(), amountMinor: 10_000, currency: 'USD', status: 'SUCCEEDED', providerPaymentReference: `affiliate-payment-${period}`, completedAt: new Date() } }); payments.push(payment.id); await database.$transaction((tx) => createCommissionForPayment(tx, payment.id)); }
    expect(await database.affiliateConversion.count({ where: { attributionId: attribution.id } })).toBe(2); expect(await database.affiliateCommission.count({ where: { affiliateId: profile.id } })).toBe(2); await database.$transaction((tx) => createCommissionForPayment(tx, payments[0]!)); expect(await database.affiliateCommission.count({ where: { affiliateId: profile.id } })).toBe(2);
    await database.$transaction((tx) => reverseCommissionForPayment(tx, payments[1]!, 'Subscription cancelled')); expect((await database.affiliateCommission.findFirstOrThrow({ where: { conversion: { paymentTransactionId: payments[1]! } } })).status).toBe('REVERSED');
    const payable = await database.affiliateCommission.findFirstOrThrow({ where: { affiliateId: profile.id, status: 'PAYABLE' } }); const key = crypto.randomUUID(); const payout = await database.affiliatePayout.create({ data: { affiliateId: profile.id, affiliateTenantId, idempotencyKey: key, amountMinor: payable.amountMinor, currency: payable.currency } }); await database.affiliateCommission.update({ where: { id: payable.id }, data: { payoutId: payout.id } }); await expect(database.affiliatePayout.create({ data: { affiliateId: profile.id, affiliateTenantId, idempotencyKey: key, amountMinor: payable.amountMinor, currency: payable.currency } })).rejects.toThrow(); expect(await database.affiliatePayout.count({ where: { idempotencyKey: key } })).toBe(1);
