  it('protects Owner controls, settings, audit integrity, session revocation, and integration credentials', async () => {
    const ownerRole = await database.role.findFirstOrThrow({ where: { name: 'Owner', tenantId: null } }); const ownerTenant = await database.tenant.create({ data: { name: 'Control owner', slug: `control-owner-${crypto.randomUUID()}` } }); const ownerUser = await database.user.create({ data: { email: 'control-owner@example.test', passwordHash: await hashPassword(password), status: 'APPROVED', emailVerifiedAt: new Date() } }); await database.tenantMembership.create({ data: { tenantId: ownerTenant.id, userId: ownerUser.id, status: 'ACTIVE' } }); await database.userRole.create({ data: { tenantId: ownerTenant.id, userId: ownerUser.id, roleId: ownerRole.id } }); const challenge = (await login('owner', ownerUser.email)).json().challengeToken as string; const enrollment = (await app.inject({ method: 'POST', url: '/v1/auth/mfa/enroll', payload: { token: challenge } })).json(); const verified = await app.inject({ method: 'POST', url: '/v1/auth/mfa/confirm', payload: { challengeToken: challenge, code: totp(enrollment.secret) } }); const ownerCookie = cookieFrom(verified.headers['set-cookie']);
    const customerToken = await register('Customer', 'control-customer@example.test'); await app.inject({ method: 'POST', url: '/v1/auth/verify-email', payload: { token: customerToken } }); const customerLogin = await login('customer', 'control-customer@example.test'); const customerCookie = cookieFrom(customerLogin.headers['set-cookie']); const customerId = customerLogin.json().user.id as string;
    expect((await app.inject({ method: 'GET', url: '/v1/owner/control/users', headers: { cookie: customerCookie } })).statusCode).toBe(403); expect((await app.inject({ method: 'GET', url: '/v1/owner/control/users', headers: { cookie: ownerCookie } })).statusCode).toBe(200);
    expect((await app.inject({ method: 'POST', url: '/v1/auth/register', payload: { email: 'public-specialist@example.test', password, displayName: 'Public Specialist', organizationName: 'Unauthorized Staff', role: 'Cybersecurity Specialist' } })).statusCode).toBe(400);
    const specialistInvite=await app.inject({method:'POST',url:'/v1/owner/control/specialists',headers:{cookie:ownerCookie},payload:{email:'owner-created-specialist@example.test',displayName:'Owner Created Specialist'}});expect(specialistInvite.statusCode).toBe(201);expect(specialistInvite.json().inviteSent).toBe(true);const specialist=await database.user.findUniqueOrThrow({where:{email:'owner-created-specialist@example.test'},include:{memberships:true,userRoles:{include:{role:true}}}});expect(specialist.status).toBe('APPROVED');expect(specialist.memberships).toEqual(expect.arrayContaining([expect.objectContaining({tenantId:ownerTenant.id,status:'ACTIVE'})]));expect(specialist.userRoles.some((assignment)=>assignment.role.name==='Cybersecurity Specialist')).toBe(true);
    expect((await app.inject({ method: 'PUT', url: '/v1/owner/control/settings/defaultMonitoringIntervalMinutes', headers: { cookie: ownerCookie }, payload: { value: 45 } })).statusCode).toBe(200); expect((await database.systemSetting.findUniqueOrThrow({ where: { key: 'defaultMonitoringIntervalMinutes' } })).value).toBe(45);
    await database.systemSetting.create({ data: { key: 'notificationCooldownMinutes', value: 60, description: 'Protected test invariant', securityInvariant: true, changedByUserId: ownerUser.id } }); expect((await app.inject({ method: 'PUT', url: '/v1/owner/control/settings/notificationCooldownMinutes', headers: { cookie: ownerCookie }, payload: { value: 1 } })).statusCode).toBe(403);
    const secret = 'phase10-super-secret-credential'; const integration = await app.inject({ method: 'POST', url: '/v1/owner/control/integrations', headers: { cookie: ownerCookie }, payload: { type: 'STORAGE', name: 'Test object storage', adapterKey: 's3-compatible', enabled: true, credentials: secret, configuration: { region: 'test-1' } } }); expect(integration.statusCode).toBe(201); expect(JSON.stringify(integration.json())).not.toContain(secret); const stored = await database.platformIntegration.findUniqueOrThrow({ where: { id: integration.json().id } }); expect(stored.encryptedCredentials).not.toContain(secret);
    expect((await app.inject({ method: 'POST', url: `/v1/owner/control/users/${customerId}/revoke-sessions`, headers: { cookie: ownerCookie } })).json().revoked).toBe(1); expect((await app.inject({ method: 'GET', url: '/v1/auth/me', headers: { cookie: customerCookie } })).statusCode).toBe(401);
    const audit = await database.auditLog.findMany({ where: { action: { in: ['owner.specialist_created', 'system.setting_changed', 'integration.created', 'owner.user_sessions_revoked'] } } }); expect(audit).toHaveLength(4); expect(JSON.stringify(audit)).not.toContain(secret); const exported = await app.inject({ method: 'GET', url: '/v1/owner/control/audit-logs/export', headers: { cookie: ownerCookie } }); expect(exported.statusCode).toBe(200); expect(exported.headers['content-type']).toContain('text/csv'); expect(exported.body).not.toContain(secret);
  });

  it('deduplicates communication, retries email, isolates notifications, and protects signed reports', async () => {
    const tokenA=await register('Customer','phase11-a@example.test');await app.inject({method:'POST',url:'/v1/auth/verify-email',payload:{token:tokenA}});const loginA=await login('customer','phase11-a@example.test');const cookieA=cookieFrom(loginA.headers['set-cookie']);const identityA=(await app.inject({method:'GET',url:'/v1/auth/me',headers:{cookie:cookieA}})).json();const tenantA=identityA.tenant.id as string;const userA=identityA.user.id as string;
    const tokenB=await register('Customer','phase11-b@example.test');await app.inject({method:'POST',url:'/v1/auth/verify-email',payload:{token:tokenB}});const loginB=await login('customer','phase11-b@example.test');const cookieB=cookieFrom(loginB.headers['set-cookie']);
    const request={tenantId:tenantA,recipientId:userA,eventType:'SCAN_COMPLETED' as const,deduplicationKey:'phase11-scan-completed',title:'Scan completed',message:'The authorized scan completed.',actionUrl:'/customer/websites/site/scans'};const first=await publishCommunicationEvent(request);const second=await publishCommunicationEvent(request);expect(second).toEqual({eventId:first.eventId,duplicate:true});expect(await database.communicationEvent.count({where:{deduplicationKey:request.deduplicationKey}})).toBe(1);
    const emailJobs:string[]=[];await processCommunicationEvent(first.eventId,{add:async(_name:string,data:unknown)=>{emailJobs.push((data as {deliveryId:string}).deliveryId);return{} as never;}} as never);await processCommunicationEvent(first.eventId,{add:async()=>({} as never)} as never);expect(await database.notification.count({where:{eventId:first.eventId}})).toBe(1);expect(await database.emailDelivery.count({where:{eventId:first.eventId}})).toBe(1);expect(emailJobs).toHaveLength(1);
    const own=await app.inject({method:'GET',url:'/v1/notifications',headers:{cookie:cookieA}});const other=await app.inject({method:'GET',url:'/v1/notifications',headers:{cookie:cookieB}});expect(own.json().some((item:{eventId?:string})=>item.eventId===first.eventId)).toBe(true);expect(other.json().some((item:{eventId?:string})=>item.eventId===first.eventId)).toBe(false);
    const sharedTenantUser=await database.user.create({data:{email:'phase11-shared@example.test',passwordHash:await hashPassword(password),status:'APPROVED',emailVerifiedAt:new Date()}});const customerRole=await database.role.findFirstOrThrow({where:{name:'Customer',tenantId:null}});await database.tenantMembership.create({data:{tenantId:tenantA,userId:sharedTenantUser.id,status:'ACTIVE'}});await database.userRole.create({data:{tenantId:tenantA,userId:sharedTenantUser.id,roleId:customerRole.id}});const beforeOverview=(await app.inject({method:'GET',url:'/v1/customer/overview',headers:{cookie:cookieA}})).json().unreadNotifications as number;await database.notification.create({data:{tenantId:tenantA,recipientUserId:sharedTenantUser.id,title:'Private to another member',body:'Must not affect this user'}});const afterOverview=(await app.inject({method:'GET',url:'/v1/customer/overview',headers:{cookie:cookieA}})).json().unreadNotifications as number;expect(afterOverview).toBe(beforeOverview);
    const delivery=await database.emailDelivery.findUniqueOrThrow({where:{eventId:first.eventId}});let attempts=0;const retryingProvider:EmailProvider={async send(message){attempts+=1;if(attempts===1)throw new Error('SMTP_TEMPORARY_FAILURE');expect(message.idempotencyKey).toBe(delivery.idempotencyKey);return{providerMessageId:'provider-phase11'};}};await expect(processEmailDelivery({data:{deliveryId:delivery.id},attemptsMade:0,opts:{attempts:3}} as never,retryingProvider)).rejects.toThrow();expect((await database.emailDelivery.findUniqueOrThrow({where:{id:delivery.id}})).status).toBe('RETRYING');await processEmailDelivery({data:{deliveryId:delivery.id},attemptsMade:1,opts:{attempts:3}} as never,retryingProvider);expect(await database.emailDelivery.findUniqueOrThrow({where:{id:delivery.id}})).toMatchObject({status:'DELIVERED',attempts:2,providerMessageId:'provider-phase11'});
    const site=await database.website.create({data:{tenantId:tenantA,name:'Phase 11 site',url:'https://example.com/',normalizedHost:'example.com',connectionStatus:'VERIFIED',connectedAt:new Date()}});const scan=await database.scan.create({data:{tenantId:tenantA,websiteId:site.id,status:'SUCCEEDED',progress:100,completedAt:new Date()}});const report=await database.report.create({data:{tenantId:tenantA,websiteId:site.id,requestedByUserId:userA,type:'SECURITY_SCAN',sourceId:scan.id,title:'Authorized scan report'}});await processReport(report.id,environment);const completed=await database.report.findUniqueOrThrow({where:{id:report.id}});expect(completed).toMatchObject({status:'SUCCEEDED'});expect(completed.integrityHash).toHaveLength(64);expect(completed.signature).toHaveLength(64);const download=await app.inject({method:'GET',url:`/v1/websites/${site.id}/reports/${report.id}/download`,headers:{cookie:cookieA}});expect(download.statusCode).toBe(200);expect(download.headers['x-content-sha256']).toBe(completed.integrityHash);expect((await app.inject({method:'GET',url:`/v1/websites/${site.id}/reports/${report.id}/download`,headers:{cookie:cookieB}})).statusCode).toBe(404);expect((await app.inject({method:'GET',url:`/v1/websites/${site.id}/chat/stream`,headers:{cookie:cookieB,connection:'Upgrade',upgrade:'websocket','x-tenant-id':tenantA}})).statusCode).toBe(404);
  });
